import json,hashlib
def normalize(value):
 if isinstance(value,dict):return {k:normalize(v) for k,v in sorted(value.items())}
 if isinstance(value,list):
  out=[normalize(v) for v in value]
  if out and all(isinstance(x,dict) and isinstance(x.get("name"),str) for x in out):
   assert len({x["name"] for x in out})==len(out),"duplicate named item"
   out.sort(key=lambda x:x["name"])
  return out
 return value
def ident(d):return (d["kind"],d["metadata"].get("namespace",""),d["metadata"]["name"])
actual=sorted([normalize(d) for d in docs],key=ident)
expected=json.loads(EXPECTED_JSON)
assert [ident(d) for d in actual]==[ident(d) for d in expected],"resource scope/identity changed"
def unchanged(a,b,path=()):
 if list(path) in MUTABLE_PATHS:return
 assert type(a) is type(b),(path,"type of fixed fixture changed")
 if isinstance(b,dict):
  flexible={p[len(path)] for p in MUTABLE_PATHS if len(p)>len(path) and p[:len(path)]==list(path)}
  assert set(a)-flexible==set(b)-flexible,(path,"unexpected fixed keys")
  for key in set(b)-flexible:unchanged(a[key],b[key],path+(key,))
  for key in flexible:
   if key in a and key in b:unchanged(a[key],b[key],path+(key,))
   elif list(path+(key,)) not in MUTABLE_PATHS:assert False,(path,key,"missing required subtree")
 elif isinstance(b,list):
  assert len(a)==len(b),(path,"fixed list cardinality changed")
  for i,(x,y) in enumerate(zip(a,b)):unchanged(x,y,path+(i,))
 else:assert a==b,(path,"fixed fixture changed")
unchanged(actual,expected)
for file,digest in FIXED_FILES.items():
 assert hashlib.sha256(pathlib.Path(file).read_text(encoding="utf8").encode("utf8")).hexdigest()==digest,"immutable supplied material changed"
cluster_kinds={"Namespace","PersistentVolume","StorageClass","PriorityClass"}
def podspecs(d):
 k=d["kind"]
 if k=="Pod":return [d["spec"]]
 if k in {"Deployment","StatefulSet","DaemonSet","Job"}:return [d["spec"]["template"]["spec"]]
 if k=="CronJob":return [d["spec"]["jobTemplate"]["spec"]["template"]["spec"]]
 return []
for d in docs:
 if d["kind"] in cluster_kinds:assert "namespace" not in d["metadata"],"cluster resource has namespace"
 else:assert d["metadata"].get("namespace")=="training","outside training namespace"
 if d["kind"]=="Namespace":assert d["metadata"]["name"]=="training"
 if d["kind"] in {"Deployment","StatefulSet","DaemonSet"}:
  labels=d["spec"]["template"]["metadata"]["labels"]
  assert all(labels.get(k)==v for k,v in d["spec"]["selector"]["matchLabels"].items()),"controller selector mismatch"
 for p in podspecs(d):
  no_external(p)
  volumes=p.get("volumes",[]);vnames=[v["name"] for v in volumes]
  vnames += [v["metadata"]["name"] for v in d.get("spec",{}).get("volumeClaimTemplates",[])]
  assert len(vnames)==len(set(vnames)),"duplicate volume name"
  containers=p.get("containers",[])+p.get("initContainers",[])
  assert len({c["name"] for c in containers})==len(containers),"duplicate container name"
  for c in containers:
   sec=c.get("securityContext",{})
   assert sec.get("privileged",False) is False,"privileged container forbidden"
   assert not sec.get("capabilities",{}).get("add"),"added capability forbidden"
   for m in c.get("volumeMounts",[])+c.get("volumeDevices",[]):
    assert m["name"] in vnames,"mount/device references missing volume"
   env=c.get("env",[])
   assert len(env)==len({e["name"] for e in env}),"duplicate env name"
  for v in volumes:
   if "configMap" in v:
    matches=[x for x in docs if x["kind"]=="ConfigMap" and x["metadata"]["name"]==v["configMap"]["name"]]
    assert len(matches)==1,"ConfigMap volume reference missing"
   if "persistentVolumeClaim" in v:
    matches=[x for x in docs if x["kind"]=="PersistentVolumeClaim" and x["metadata"]["name"]==v["persistentVolumeClaim"]["claimName"]]
    assert len(matches)==1,"PVC volume reference missing"

