 assert hashlib.sha256(pathlib.Path(file).read_text(encoding="utf8").encode("utf8")).hexdigest()==digest,"immutable supplied material changed"
cluster_kinds={"Namespace","PersistentVolume","StorageClass","PriorityClass"}
def podspecs(d):
 k=d["kind"]
 if k=="Pod":return [d["spec"]]
 if k in {"Deployment","StatefulSet","DaemonSet","Job"}:return [d["spec"]["template"]["spec"]]
 if k=="CronJob":return [d["spec"]["jobTemplate"]["spec"]["template"]["spec"]]
 return []
for d in docs:
 if d["kind"] in cluster_kinds:assert "namespace" not in d["metadata"],"cluster resource has namespace"
 else:assert d["metadata"].get("namespace")=="training","outside training namespace"
 if d["kind"]=="Namespace":assert d["metadata"]["name"]=="training"
 if d["kind"] in {"Deployment","StatefulSet","DaemonSet"}:
  labels=d["spec"]["template"]["metadata"]["labels"]
  assert all(labels.get(k)==v for k,v in d["spec"]["selector"]["matchLabels"].items()),"controller selector mismatch"
 for p in podspecs(d):
  no_external(p)
  volumes=p.get("volumes",[]);vnames=[v["name"] for v in volumes]
  vnames += [v["metadata"]["name"] for v in d.get("spec",{}).get("volumeClaimTemplates",[])]
  assert len(vnames)==len(set(vnames)),"duplicate volume name"
  containers=p.get("containers",[])+p.get("initContainers",[])
  assert len({c["name"] for c in containers})==len(containers),"duplicate container name"
