import pathlib, yaml
class UniqueLoader(yaml.SafeLoader):pass
def mapping(loader,node,deep=False):
    out={}
    for key_node,value_node in node.value:
        key=loader.construct_object(key_node,deep=deep)
        assert key not in out,"duplicate YAML key"
        out[key]=loader.construct_object(value_node,deep=deep)
    return out
UniqueLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,mapping)
docs=[x for x in yaml.load_all(pathlib.Path("manifest.yaml").read_text(encoding="utf8"),Loader=UniqueLoader) if x is not None]
assert all(isinstance(x,dict) for x in docs),"resource must be mapping"
seen=set()
for x in docs:
    assert x.get("apiVersion") and x.get("kind") and x.get("metadata",{}).get("name")
    identity=(x["kind"],x["metadata"].get("namespace",""),x["metadata"]["name"])
    assert identity not in seen,"duplicate resource identity"
    seen.add(identity)
def resource(kind,name):
    found=[x for x in docs if x["kind"]==kind and x["metadata"]["name"]==name]
    assert len(found)==1,(kind,name)
    return found[0]
def container(p,name="main"):
    found=[x for x in p["containers"] if x["name"]==name]
    assert len(found)==1
    return found[0]
def no_external(p):
    assert not p.get("hostNetwork",False) and not p.get("hostPID",False) and not p.get("hostIPC",False)
    assert all("hostPath" not in v for v in p.get("volumes",[]))

